"use client";

import { createContext, useContext, useMemo, useState } from "react";
import {
  Activity, AlertTriangle, ArrowDownToLine, ArrowRight, Boxes, BookOpenCheck, Check,
  ChevronRight, CircleAlert, Clock3, ContactRound, FileCheck2, Filter, Gauge,
  ListChecks, LockKeyhole, PackageSearch, Plus, RotateCcw, Search,
  Send, Settings2, Truck, UserRound,
  Users, Workflow, XCircle,
} from "lucide-react";
import { Modal, StatusBadge, inputClass } from "@/components/admin/ui";
import Dropdown from "@/components/ui/dropdown";
import type { AdminNavItem } from "@/lib/admin-navigation";
import { cn } from "@/lib/utils";

type Tone = "neutral" | "positive" | "warning" | "critical" | "navy";
type WorkspaceAction = { label: string; entity?: string };
type ActionPayload = Record<string, string>;
type WorkspaceActionContextValue = { openAction(label: string, entity?: string): void };

const WorkspaceActionContext = createContext<WorkspaceActionContextValue | null>(null);

function useWorkspaceAction() {
  const context = useContext(WorkspaceActionContext);
  if (!context) throw new Error("Workspace actions must be used inside a module workspace");
  return context;
}

const routeCopy: Record<string, { eyebrow: string; intro: string; primary: string; kind: string }> = {
  "/alerts-attention": { eyebrow: "Attention queue", intro: "Prioritize operational risk, ownership gaps, and decisions waiting on the Super Admin.", primary: "Create alert rule", kind: "queue" },
  "/operations/shipments": { eyebrow: "Shipment register", intro: "Search every client shipment and move quickly from exception to accountable owner.", primary: "Export register", kind: "register" },
  "/operations/bookings": { eyebrow: "Booking desk", intro: "Create and supervise single or bulk bookings with documents and courier context in view.", primary: "New booking", kind: "form" },
  "/operations/tracking": { eyebrow: "Movement control", intro: "Follow milestones, identify stalled movement, and record the next operational action.", primary: "Track shipment", kind: "timeline" },
  "/operations/pickups": { eyebrow: "Pickup control", intro: "Coordinate scheduled collections, capacity, driver ownership, and failed pickup recovery.", primary: "Schedule pickup", kind: "schedule" },
  "/operations/returns": { eyebrow: "RTO desk", intro: "Review automatic return movement and complete the documents required for the next leg.", primary: "Review documents", kind: "documents" },
  "/operations/exceptions": { eyebrow: "Exception desk", intro: "Triage holds, delays, and failed services with an owner and resolution deadline.", primary: "Assign exception", kind: "queue" },
  "/clients": { eyebrow: "Client directory", intro: "See account health, operational volume, ownership, and the next client decision.", primary: "Add client", kind: "directory" },
  "/clients/onboarding": { eyebrow: "Verification queue", intro: "Review business identity, KYC documents, and the decision required to activate an account.", primary: "Start onboarding", kind: "verification" },
  "/clients/activity": { eyebrow: "Client timeline", intro: "Trace shipment, support, ownership, and administrative activity by client.", primary: "Export activity", kind: "timeline" },
  "/departments": { eyebrow: "Organization map", intro: "Understand functional ownership, manager coverage, and available team capacity.", primary: "Create department", kind: "organization" },
  "/tasks": { eyebrow: "Work queue", intro: "Monitor overdue work and move operational tasks to the employee best placed to complete them.", primary: "Create task", kind: "tasks" },
  "/employee-activity": { eyebrow: "Activity ledger", intro: "Review employee actions with actor, entity, timestamp, and security context.", primary: "Export ledger", kind: "timeline" },
  "/support/tickets": { eyebrow: "Support inbox", intro: "Resolve client conversations with shipment context, ownership, and SLA visibility.", primary: "New ticket", kind: "inbox" },
  "/support/sla-escalations": { eyebrow: "SLA monitor", intro: "Focus the team on due-soon and breached support commitments before they become escalations.", primary: "Configure SLA", kind: "monitor" },
  "/finance/wallets": { eyebrow: "Wallet control", intro: "Review client balances, holds, and adjustments before changing available credit.", primary: "Record adjustment", kind: "ledger" },
  "/finance/billing-invoices": { eyebrow: "Invoice desk", intro: "Manage invoice status, billing exceptions, and approval exposure in one register.", primary: "Create invoice", kind: "ledger" },
  "/finance/transactions": { eyebrow: "Transaction ledger", intro: "Reconcile wallet and billing movements with client and actor attribution.", primary: "Export ledger", kind: "ledger" },
  "/insights/analytics": { eyebrow: "Analytics studio", intro: "Compare operational trends across clients, employees, couriers, and services.", primary: "Build report", kind: "analytics" },
  "/insights/reports": { eyebrow: "Report catalogue", intro: "Generate governed reports, schedule recurring exports, and inspect download history.", primary: "Create report", kind: "reports" },
  "/insights/performance": { eyebrow: "Performance center", intro: "Compare service, client, courier, and employee performance against useful operating signals.", primary: "Compare teams", kind: "analytics" },
  "/automation/workflow-rules": { eyebrow: "Workflow builder", intro: "Define event-driven routing, assignment, and escalation rules with visible execution history.", primary: "Create rule", kind: "rules" },
  "/automation/notification-rules": { eyebrow: "Notification routing", intro: "Control which events reach which recipients, with severity and channel made explicit.", primary: "Add notification rule", kind: "rules" },
  "/automation/scheduled-jobs": { eyebrow: "Job monitor", intro: "Supervise scheduled workers, retries, and the next run of system processes.", primary: "Run job", kind: "monitor" },
  "/integrations/couriers": { eyebrow: "Courier health", intro: "Monitor carrier connectivity, latency, service configuration, and recent API failures.", primary: "Connect courier", kind: "integrations" },
  "/integrations/channels": { eyebrow: "Channel health", intro: "Manage email, WhatsApp, and SMS delivery channels and their failure states.", primary: "Add channel", kind: "integrations" },
  "/integrations/api-webhooks": { eyebrow: "Developer access", intro: "Govern API keys, webhook endpoints, scopes, and delivery attempts.", primary: "Create API key", kind: "integrations" },
  "/system/security-sessions": { eyebrow: "Security monitor", intro: "Review active sessions, authentication risk, and access that needs revocation.", primary: "Revoke session", kind: "security" },
  "/system/notifications": { eyebrow: "Notification center", intro: "Review operational and administrative events by priority, category, and acknowledgement state.", primary: "Mark all read", kind: "inbox" },
  "/system/settings": { eyebrow: "Platform controls", intro: "Manage organization defaults and policy configuration with an explicit change boundary.", primary: "Save settings", kind: "settings" },
};

const sampleRows = [
  ["Northwind Pharma", "Shipment exception", "Owner action required", "12 min", "critical"],
  ["Arvind Components", "Pickup cutoff", "Driver assignment", "28 min", "warning"],
  ["Jaipur Craft House", "KYC document", "Review pending", "1 hr", "warning"],
  ["Orion Auto Parts", "Invoice approval", "Ready for review", "3 hr", "positive"],
] as const;

type SerializableAdminNavItem = Omit<AdminNavItem, "icon">;

const iconByRoute = {
  "/alerts-attention": AlertTriangle,
  "/operations/shipments": Boxes,
  "/operations/bookings": BookOpenCheck,
  "/operations/tracking": PackageSearch,
  "/operations/pickups": Truck,
  "/operations/returns": RotateCcw,
  "/clients/onboarding": ContactRound,
} as const;

export default function AdminModuleWorkspace({ module }: { module: SerializableAdminNavItem }) {
  const copy = routeCopy[module.href] ?? { eyebrow: "Module workspace", intro: module.description, primary: "Open workspace", kind: "settings" };
  const Icon = iconByRoute[module.href as keyof typeof iconByRoute] ?? Boxes;
  const [query, setQuery] = useState("");
  const [notice, setNotice] = useState<string | null>(null);
  const [filter, setFilter] = useState("All");
  const [action, setAction] = useState<WorkspaceAction | null>(null);
  const [actionHistory, setActionHistory] = useState<string[]>([]);
  const rows = useMemo(() => sampleRows.filter((row) => `${row[0]} ${row[1]} ${row[2]}`.toLowerCase().includes(query.toLowerCase()) && (filter === "All" || row[4] === filter)), [filter, query]);

  function runPrimary() {
    if (/export/i.test(copy.primary)) {
      const csv = ["Entity,Issue,Next action,Age,Severity", ...sampleRows.map((row) => row.join(","))].join("\n");
      const link = document.createElement("a"); link.href = `data:text/csv;charset=utf-8,${encodeURIComponent(csv)}`; link.download = `${module.href.slice(1).replaceAll("/", "-")}-export.csv`; link.click();
      setNotice(`${copy.primary} downloaded with ${sampleRows.length} records.`);
      return;
    }
    if (/mark all read/i.test(copy.primary)) {
      setActionHistory((current) => [`${copy.primary} · ${module.label}`, ...current].slice(0, 5));
      setNotice(`All ${module.label.toLowerCase()} are marked as read.`);
      return;
    }
    openAction(copy.primary, module.label);
  }

  function openAction(label: string, entity?: string) { setAction({ label, entity }); }
  function submitAction(payload: ActionPayload) {
    if (!action) return;
    const details = Object.entries(payload).filter(([, value]) => value.trim()).map(([key, value]) => `${key}: ${value}`).join(" · ");
    const result = `${action.label}${action.entity ? ` · ${action.entity}` : ""}${details ? ` · ${details}` : ""}`;
    setActionHistory((current) => [result, ...current].slice(0, 5));
    setAction(null); setNotice(`${result} saved locally and ready for backend submission.`);
  }

  return <WorkspaceActionContext.Provider value={{ openAction }}><div className="flex h-full min-h-0 w-full flex-col gap-5">
    <header className="flex flex-col gap-4 border-b border-border/70 pb-5 xl:flex-row xl:items-end xl:justify-between">
      <div className="flex items-start gap-3"><div className="grid size-10 shrink-0 place-items-center rounded-xl bg-primary/10 text-primary"><Icon className="size-[18px]" /></div><div><p className="text-[10px] font-bold uppercase tracking-[0.16em] text-primary">{copy.eyebrow}</p><h1 className="mt-1 text-2xl font-semibold tracking-[-0.035em]">{module.label}</h1><p className="mt-1 max-w-3xl text-xs leading-5 text-muted-foreground">{copy.intro}</p></div></div>
      <div className="flex flex-wrap items-center gap-2"><StatusBadge tone={module.status === "planned" ? "warning" : "positive"}>{module.status === "planned" ? "Workflow planned" : "Prototype workspace"}</StatusBadge><button onClick={runPrimary} className="inline-flex h-9 items-center gap-2 rounded-lg bg-primary px-3 text-xs font-semibold text-primary-foreground shadow-sm hover:bg-primary/90"><Plus className="size-3.5" />{copy.primary}</button></div>
    </header>
    {notice && <button onClick={() => setNotice(null)} className="flex w-full items-center justify-between rounded-lg border border-primary/20 bg-primary/5 px-3 py-2 text-left text-xs text-primary"><span>{notice}</span><XCircle className="size-4" /></button>}
    <div className="module-workspace-content min-h-0 flex-1">
      {copy.kind === "form" && <BookingWorkspace />}
      {copy.kind === "register" && <RegisterWorkspace query={query} setQuery={setQuery} rows={rows} />}
      {copy.kind === "timeline" && <TimelineWorkspace query={query} setQuery={setQuery} />}
      {copy.kind === "documents" && <DocumentsWorkspace />}
      {copy.kind === "verification" && <VerificationWorkspace />}
      {copy.kind === "schedule" && <ScheduleWorkspace />}
      {copy.kind === "directory" && <DirectoryWorkspace query={query} setQuery={setQuery} />}
      {copy.kind === "organization" && <OrganizationWorkspace />}
      {copy.kind === "tasks" && <TasksWorkspace />}
      {copy.kind === "inbox" && <InboxWorkspace query={query} setQuery={setQuery} filter={filter} setFilter={setFilter} rows={rows} />}
      {copy.kind === "ledger" && <LedgerWorkspace query={query} setQuery={setQuery} />}
      {copy.kind === "analytics" && <AnalyticsWorkspace />}
      {copy.kind === "reports" && <ReportsWorkspace />}
      {copy.kind === "rules" && <RulesWorkspace />}
      {copy.kind === "monitor" && <MonitorWorkspace />}
      {copy.kind === "integrations" && <IntegrationsWorkspace />}
      {copy.kind === "security" && <SecurityWorkspace />}
      {(copy.kind === "queue" || copy.kind === "settings") && <QueueOrSettingsWorkspace kind={copy.kind} query={query} setQuery={setQuery} filter={filter} setFilter={setFilter} rows={rows} />}
    </div>
    {actionHistory.length > 0 && <div className="rounded-xl border border-border bg-card px-4 py-3 shadow-xs"><div className="flex items-center justify-between"><p className="text-xs font-semibold">Recent actions</p><span className="text-[10px] text-muted-foreground">Local audit queue</span></div><div className="mt-2 flex flex-wrap gap-2">{actionHistory.map((item) => <StatusBadge key={item} tone="positive">{item}</StatusBadge>)}</div></div>}
    <ActionDialog key={action ? `${action.label}-${action.entity ?? "workspace"}` : "closed"} action={action} onClose={() => setAction(null)} onSubmit={submitAction} />
  </div></WorkspaceActionContext.Provider>;
}

function WorkspaceCard({ title, detail, children, className }: { title: string; detail?: string; children: React.ReactNode; className?: string }) { return <section className={cn("flex h-full min-h-0 flex-col overflow-hidden rounded-xl border border-border bg-card shadow-xs", className)}><div className="flex shrink-0 items-center justify-between border-b border-border/70 px-4 py-3"><div><h2 className="text-sm font-semibold">{title}</h2>{detail && <p className="mt-1 text-[11px] text-muted-foreground">{detail}</p>}</div></div><div className="min-h-0 flex-1">{children}</div></section>; }
function Toolbar({ query, setQuery, filter, setFilter, placeholder = "Search workspace" }: { query: string; setQuery(v: string): void; filter?: string; setFilter?: (v: string) => void; placeholder?: string }) { const { openAction } = useWorkspaceAction(); return <div className="flex flex-col gap-2 border-b border-border/70 p-3 sm:flex-row"><div className="relative flex-1"><Search className="absolute left-3 top-1/2 size-3.5 -translate-y-1/2 text-muted-foreground" /><input value={query} onChange={(e) => setQuery(e.target.value)} className={cn(inputClass, "h-9 pl-9 text-xs")} placeholder={placeholder} /></div>{setFilter && <div className="flex gap-1 rounded-lg bg-muted p-1">{["All", "critical", "warning", "positive"].map((item) => <button key={item} onClick={() => setFilter(item)} className={cn("rounded-md px-2.5 py-1 text-[10px] font-semibold capitalize", filter === item ? "bg-card text-foreground shadow-xs" : "text-muted-foreground")}>{item}</button>)}</div>}<button onClick={() => openAction("Open advanced filters")} className="inline-flex h-9 items-center justify-center gap-1.5 rounded-lg border border-border px-3 text-xs font-semibold text-muted-foreground hover:bg-muted"><Filter className="size-3.5" />Filter</button></div>; }
function MetricStrip({ items }: { items: [string, string, Tone][] }) { return <div className="grid border-b border-border/70 sm:grid-cols-3">{items.map(([label, value, tone], i) => <div key={label} className={cn("px-4 py-3", i > 0 && "border-t border-border/70 sm:border-l sm:border-t-0")}><p className={cn("text-xl font-bold tabular-nums", tone === "critical" ? "text-destructive" : tone === "warning" ? "text-amber-600" : tone === "positive" ? "text-emerald-600" : "text-foreground")}>{value}</p><p className="mt-0.5 text-[10px] text-muted-foreground">{label}</p></div>)}</div>; }
function Row({ item }: { item: readonly [string, string, string, string, string] }) { const { openAction } = useWorkspaceAction(); return <button onClick={() => openAction(`Inspect ${item[1]}`, item[0])} className="grid w-full grid-cols-[10px_minmax(150px,1.2fr)_minmax(140px,1fr)_72px_22px] items-center gap-3 px-4 py-3 text-left transition-colors hover:bg-muted/50"><span className={cn("size-2 rounded-full", item[4] === "critical" ? "bg-destructive" : item[4] === "warning" ? "bg-amber-500" : "bg-emerald-500")} /><span className="min-w-0"><span className="block truncate text-xs font-semibold">{item[0]}</span><span className="block truncate text-[10px] text-muted-foreground">{item[1]}</span></span><span className="truncate text-[11px] text-muted-foreground">{item[2]}</span><span className="text-[10px] font-semibold text-muted-foreground">{item[3]}</span><ChevronRight className="size-3.5 text-muted-foreground" /></button>; }

function RegisterWorkspace({ query, setQuery, rows }: { query: string; setQuery(v: string): void; rows: typeof sampleRows[number][] }) { return <div className="grid h-full gap-4 xl:grid-cols-[minmax(0,1fr)_320px]"><WorkspaceCard title="Shipment register" detail="Global scope · 2,481 shipments · updated just now"><MetricStrip items={[["In transit", "1,204", "navy"], ["Delivered today", "486", "positive"], ["Exceptions", "37", "critical"]]} /><Toolbar query={query} setQuery={setQuery} placeholder="Search AWB, client, courier, or city" /><div className="hidden grid-cols-[1.2fr_1fr_1fr_110px] gap-3 border-b border-border/70 bg-muted/40 px-4 py-2 text-[10px] font-bold uppercase tracking-wider text-muted-foreground"><span>Shipment / client</span><span>Movement</span><span>Courier</span><span>Status</span></div>{rows.map((row) => <Row item={row} key={row[0]} />)}</WorkspaceCard><WorkspaceCard title="Selected shipment" detail="Choose a row to inspect movement and ownership"><div className="space-y-4 p-4"><div className="rounded-lg bg-muted/40 p-3"><p className="font-mono text-xs font-bold">PSS-2026-004821</p><p className="mt-1 text-[11px] text-muted-foreground">Northwind Pharma · Mumbai → Delhi</p></div><DetailLine label="Current milestone" value="Out for delivery" /><DetailLine label="Accountable owner" value="Rahul Sharma" /><DetailLine label="Next action" value="Confirm delivery attempt" /></div></WorkspaceCard></div>; }

function BookingWorkspace() {
  const [mode, setMode] = useState<"single" | "bulk">("single");
  const [form, setForm] = useState({ client: "", owner: "", consignor: "", consignee: "", pickup: "", drop: "", weight: "", length: "", width: "", height: "", invoice: "", courier: "", service: "Express", slot: "10:00–13:00" });
  const [bulkFile, setBulkFile] = useState("");
  const [created, setCreated] = useState(false);
  const [challanOpen, setChallanOpen] = useState(false);
  const [challanSaved, setChallanSaved] = useState(false);
  const [challan, setChallan] = useState({ number: "", date: "", item: "", quantity: "1", taxableValue: "", taxRate: "18", transport: "Road", notes: "" });
  const update = (key: keyof typeof form, value: string) => setForm((current) => ({ ...current, [key]: value }));
  const updateChallan = (key: keyof typeof challan, value: string) => setChallan((current) => ({ ...current, [key]: value }));
  const challanReady = Boolean(challan.number && challan.date && challan.item && challan.quantity && challan.taxableValue && form.consignor && form.consignee && form.pickup && form.drop);
  const checks = mode === "bulk"
    ? [{ label: "Upload file", ready: Boolean(bulkFile) }, { label: "Row validation", ready: false }, { label: "Documents", ready: false }, { label: "Courier mapping", ready: false }]
    : [
        { label: "Client, owner, party and route", ready: Boolean(form.client && form.owner && form.consignor && form.consignee && form.pickup && form.drop) },
        { label: "Package dimensions", ready: Boolean(form.weight && form.length && form.width && form.height) },
        { label: "Invoice / challan", ready: Boolean(form.invoice || challanSaved) },
        { label: "Courier and pickup slot", ready: Boolean(form.courier && form.slot) },
      ];
  const ready = checks.every((check) => check.ready);
  const submit = (event: React.FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    if (ready) setCreated(true);
  };
  const textField = (key: keyof typeof form, label: string, placeholder: string, type = "text", required = true) => (
    <label className="space-y-1.5">
      <span className="text-[11px] font-semibold">{label}</span>
      <input required={required} value={form[key]} onChange={(event) => update(key, event.target.value)} type={type} placeholder={placeholder} className={inputClass} />
    </label>
  );
  const dropdownField = (label: string, control: React.ReactNode) => <div className="space-y-1.5"><span className="block text-[11px] font-semibold">{label}</span>{control}</div>;
  return <div className="grid h-full min-h-0 gap-4 xl:grid-cols-[minmax(0,1.4fr)_360px]">
    <WorkspaceCard title={mode === "single" ? "Single shipment booking" : "Bulk shipment upload"} detail={mode === "single" ? "Capture the parties, route, package, and courier details required to create a shipment." : "Upload a CSV or XLSX file, validate every row, then continue with courier and document mapping."}>
      {created ? <div className="flex h-full flex-col items-center justify-center p-8 text-center">
        <div className="flex size-12 items-center justify-center rounded-full bg-emerald-50 text-emerald-600"><Check className="size-6" /></div>
        <h3 className="mt-4 text-base font-bold">Booking ready for submission</h3>
        <p className="mt-1 max-w-md text-xs text-muted-foreground">The frontend payload is complete and ready for the backend booking endpoint.</p>
        <button type="button" onClick={() => setCreated(false)} className="mt-5 h-9 rounded-lg border border-border px-4 text-xs font-semibold hover:bg-muted">Create another booking</button>
      </div> : <form onSubmit={submit} className="flex h-full min-h-0 flex-col">
        <div className="flex shrink-0 gap-2 border-b border-border/70 p-4">
          {([["single", "Single booking", "One shipment with guided validation"], ["bulk", "Bulk upload", "CSV/XLSX with row review"]] as const).map(([value, label, detail]) => <button key={value} type="button" onClick={() => setMode(value)} className={`flex-1 rounded-xl border px-3 py-3 text-left ${mode === value ? "border-primary bg-primary/5" : "border-border hover:border-primary/40"}`}><span className="block text-xs font-semibold">{label}</span><span className="mt-1 block text-[10px] text-muted-foreground">{detail}</span></button>)}
        </div>
        <div className="min-h-0 flex-1 overflow-y-auto p-4">
          {mode === "single" ? <div className="grid gap-4 sm:grid-cols-2">
            <Dropdown label="Client account" value={form.client} options={["Northwind Pharma", "Arvind Components", "Jaipur Craft House", "Orion Auto Parts"].map((value) => ({ value, label: value }))} onChange={(value) => update("client", value)} />
            <Dropdown label="Account owner" value={form.owner} options={["Rahul Sharma", "Priya Mehta", "Amit Shah", "Neha Rao"].map((value) => ({ value, label: value }))} onChange={(value) => update("owner", value)} />
            {textField("consignor", "Consignor", "Client or saved sender")}
            {textField("consignee", "Consignee", "Recipient name")}
            {textField("pickup", "Pickup address", "Full pickup address")}
            {textField("drop", "Drop / delivery address", "Full delivery address")}
            {textField("weight", "Weight (kg)", "0.00", "number")}
            {textField("length", "Length (cm)", "0", "number")}
            {textField("width", "Width (cm)", "0", "number")}
            {textField("height", "Height (cm)", "0", "number")}
            <div className="space-y-1.5"><span className="block text-[11px] font-semibold">Invoice / challan number</span><div className="flex gap-2"><input value={form.invoice} onChange={(event) => update("invoice", event.target.value)} placeholder="Document reference" className={cn(inputClass, "min-w-0 flex-1")} /><button type="button" onClick={() => setChallanOpen(true)} className="shrink-0 rounded-lg border border-primary/30 px-3 text-[11px] font-semibold text-primary hover:bg-primary/5">{challanSaved ? "Edit challan" : "Create challan"}</button></div></div>
            {dropdownField("Courier", <Dropdown label="Courier" value={form.courier} options={["Delhivery", "Blue Dart", "DTDC", "Shiprocket"].map((value) => ({ value, label: value }))} onChange={(value) => update("courier", value)} />)}
            {dropdownField("Service level", <Dropdown label="Service level" value={form.service} options={["Express", "Standard", "Same day"].map((value) => ({ value, label: value }))} onChange={(value) => update("service", value)} />)}
            {dropdownField("Pickup slot", <Dropdown label="Pickup slot" value={form.slot} options={["08:00–10:00", "10:00–13:00", "13:00–16:00"].map((value) => ({ value, label: value }))} onChange={(value) => update("slot", value)} />)}
          </div> : <label className="flex min-h-48 cursor-pointer flex-col items-center justify-center rounded-xl border border-dashed border-border bg-muted/20 p-6 text-center hover:border-primary/50">
            <Boxes className="size-8 text-primary" />
            <span className="mt-3 text-sm font-semibold">{bulkFile || "Choose CSV or XLSX file"}</span>
            <span className="mt-1 text-[11px] text-muted-foreground">Each row must include consignor, consignee, pickup, drop, package, and invoice data.</span>
            <input type="file" accept=".csv,.xlsx,.xls" className="sr-only" onChange={(event) => setBulkFile(event.target.files?.[0]?.name ?? "")} />
          </label>}
        </div>
        <div className="flex shrink-0 items-center justify-between gap-3 border-t border-border/70 p-3">
          <span className="text-[10px] text-muted-foreground">{ready ? "All required fields are complete." : "Complete the required fields to continue."}</span>
          <button type="submit" disabled={!ready} className="inline-flex h-9 items-center gap-2 rounded-lg bg-primary px-3 text-xs font-semibold text-primary-foreground disabled:cursor-not-allowed disabled:opacity-40"><ArrowRight className="size-3.5" />{mode === "bulk" ? "Validate upload" : "Continue to documents"}</button>
        </div>
      </form>}
    </WorkspaceCard>
    <Modal open={challanOpen} onClose={() => setChallanOpen(false)} title="Create delivery challan" description="Create the document that will travel with this shipment and be sent to the backend with the booking payload." size="lg">
      <div className="grid gap-4 sm:grid-cols-2">
        <label className="space-y-1.5"><span className="text-[11px] font-semibold">Challan number</span><input value={challan.number} onChange={(event) => updateChallan("number", event.target.value)} placeholder="DC-2026-0001" className={inputClass} /></label>
        <label className="space-y-1.5"><span className="text-[11px] font-semibold">Challan date</span><input type="date" value={challan.date} onChange={(event) => updateChallan("date", event.target.value)} className={inputClass} /></label>
        <div className="sm:col-span-2 rounded-xl border border-border bg-muted/30 p-3 text-[11px]"><p className="font-semibold">Document parties</p><p className="mt-1 text-muted-foreground">{form.consignor || "Consignor not entered"} → {form.consignee || "Consignee not entered"}</p><p className="mt-1 text-muted-foreground">{form.pickup || "Pickup address not entered"} → {form.drop || "Drop address not entered"}</p></div>
        <label className="space-y-1.5 sm:col-span-2"><span className="text-[11px] font-semibold">Item / goods description</span><input value={challan.item} onChange={(event) => updateChallan("item", event.target.value)} placeholder="Describe the goods being transported" className={inputClass} /></label>
        <label className="space-y-1.5"><span className="text-[11px] font-semibold">Quantity</span><input type="number" min="1" value={challan.quantity} onChange={(event) => updateChallan("quantity", event.target.value)} className={inputClass} /></label>
        <label className="space-y-1.5"><span className="text-[11px] font-semibold">Taxable value</span><input type="number" min="0" value={challan.taxableValue} onChange={(event) => updateChallan("taxableValue", event.target.value)} placeholder="0.00" className={inputClass} /></label>
        {dropdownField("Tax rate", <Dropdown label="Tax rate" value={challan.taxRate} options={["0", "5", "12", "18", "28"].map((value) => ({ value, label: `${value}%` }))} onChange={(value) => updateChallan("taxRate", value)} />)}
        {dropdownField("Transport mode", <Dropdown label="Transport mode" value={challan.transport} options={["Road", "Air", "Rail", "Courier"].map((value) => ({ value, label: value }))} onChange={(value) => updateChallan("transport", value)} />)}
        <label className="space-y-1.5 sm:col-span-2"><span className="text-[11px] font-semibold">Notes</span><textarea value={challan.notes} onChange={(event) => updateChallan("notes", event.target.value)} placeholder="Handling, package, or compliance notes" className={cn(inputClass, "min-h-20 py-2")} /></label>
      </div>
      <div className="mt-5 flex items-center justify-between gap-3 border-t border-border/70 pt-4"><span className="text-[10px] text-muted-foreground">{challanReady ? "Required challan fields are complete." : "Complete the document parties and required challan fields."}</span><button type="button" disabled={!challanReady} onClick={() => { setChallanSaved(true); update("invoice", challan.number); setChallanOpen(false); }} className="h-9 rounded-lg bg-primary px-4 text-xs font-semibold text-primary-foreground disabled:cursor-not-allowed disabled:opacity-40">Save challan</button></div>
    </Modal>
    <WorkspaceCard title="Booking readiness" detail={mode === "single" ? "Required before label generation" : "Required before row submission"}>
      <div className="divide-y divide-border/70">{checks.map((check) => <CheckRow key={check.label} label={check.label} value={check.ready ? "Ready" : "Required"} warning={!check.ready} />)}</div>
    </WorkspaceCard>
  </div>;
}
function TimelineWorkspace({ query, setQuery }: { query: string; setQuery(v: string): void }) { const { openAction } = useWorkspaceAction(); return <div className="grid gap-4 xl:grid-cols-[320px_minmax(0,1fr)]"><WorkspaceCard title="Activity stream" detail="Newest events across this module"><Toolbar query={query} setQuery={setQuery} placeholder="Search entity or actor" /><div className="divide-y divide-border/70">{["Shipment PSS-2026-004821 delivered", "Client responsibility transferred", "Pickup attempt marked failed", "Support ticket escalated"].map((item, i) => <button key={item} onClick={() => openAction("Inspect activity event", item)} className="flex w-full items-start gap-3 px-4 py-3 text-left hover:bg-muted/50"><span className={cn("mt-1.5 size-2 shrink-0 rounded-full", i === 2 ? "bg-amber-500" : "bg-primary")} /><span className="min-w-0 flex-1"><span className="block text-xs font-semibold">{item}</span><span className="mt-1 block text-[10px] text-muted-foreground">{["2 min ago", "18 min ago", "42 min ago", "1 hr ago"][i]} · System event</span></span><ChevronRight className="mt-1 size-3.5 text-muted-foreground" /></button>)}</div></WorkspaceCard><WorkspaceCard title="Event detail" detail="Select an event to inspect the before and after state"><div className="p-4"><div className="flex items-center gap-2"><Activity className="size-4 text-primary" /><p className="text-sm font-semibold">Shipment delivered</p><StatusBadge tone="positive">Completed</StatusBadge></div><div className="mt-4 grid gap-3 sm:grid-cols-2"><DetailLine label="Entity" value="PSS-2026-004821" /><DetailLine label="Actor" value="Courier webhook" /><DetailLine label="Previous state" value="Out for delivery" /><DetailLine label="New state" value="Delivered" /></div><div className="mt-4 rounded-lg border border-border bg-muted/30 p-3 text-[11px] leading-5 text-muted-foreground">Timeline events remain locally simulated until the production event stream is connected.</div></div></WorkspaceCard></div>; }
function DocumentsWorkspace() { const { openAction } = useWorkspaceAction(); return <div className="grid gap-4 lg:grid-cols-[1fr_360px]"><WorkspaceCard title="Documentation queue" detail="RTO movements waiting for an operator decision"><MetricStrip items={[["Documents pending", "12", "warning"], ["Ready for return", "28", "positive"], ["Blocked", "4", "critical"]]} /><div className="divide-y divide-border/70">{["RTO-004821 · Northwind Pharma", "RTO-004799 · Arvind Components", "RTO-004766 · Jaipur Craft House"].map((item, i) => <button key={item} onClick={() => openAction("Open document pack", item)} className="flex w-full items-center gap-3 px-4 py-3 text-left hover:bg-muted/50"><FileCheck2 className={cn("size-4", i === 0 ? "text-amber-500" : "text-emerald-500")} /><span className="min-w-0 flex-1"><span className="block truncate text-xs font-semibold">{item}</span><span className="block text-[10px] text-muted-foreground">{i === 0 ? "Invoice and delivery challan required" : "Document pack complete"}</span></span><StatusBadge tone={i === 0 ? "warning" : "positive"}>{i === 0 ? "Pending" : "Ready"}</StatusBadge></button>)}</div></WorkspaceCard><WorkspaceCard title="Document pack" detail="RTO-004821 · selected return"><div className="divide-y divide-border/70"><CheckRow label="Original invoice" value="Missing" warning /><CheckRow label="Delivery challan" value="Uploaded" /><CheckRow label="E-Way Bill" value="Not required" /><CheckRow label="Return movement" value="Automatic" /></div></WorkspaceCard></div>; }
function VerificationWorkspace() { const { openAction } = useWorkspaceAction(); return <div className="grid gap-4 xl:grid-cols-[minmax(0,1fr)_340px]"><WorkspaceCard title="Verification queue" detail="New accounts sorted by risk and document completeness"><div className="flex flex-wrap gap-2 border-b border-border/70 p-3"><StatusBadge tone="warning">8 awaiting review</StatusBadge><StatusBadge tone="critical">2 missing PAN</StatusBadge><StatusBadge tone="positive">14 approved this month</StatusBadge></div><div className="divide-y divide-border/70">{["Northwind Pharma", "Jaipur Craft House", "Orion Auto Parts", "Arvind Components"].map((name, i) => <button key={name} onClick={() => openAction("Review KYC application", name)} className="flex w-full items-center gap-3 px-4 py-3 text-left hover:bg-muted/50"><div className="grid size-8 place-items-center rounded-lg bg-primary/10 text-primary"><UserRound className="size-4" /></div><span className="min-w-0 flex-1"><span className="block text-xs font-semibold">{name}</span><span className="block text-[10px] text-muted-foreground">GSTIN {i === 1 ? "missing" : "submitted"} · {i + 1} documents pending</span></span><StatusBadge tone={i === 1 ? "critical" : "warning"}>{i === 1 ? "Needs info" : "Review"}</StatusBadge></button>)}</div></WorkspaceCard><WorkspaceCard title="Review checklist" detail="Make a decision only after the evidence is complete"><div className="space-y-3 p-4"><CheckRow label="Business information" value="Submitted" /><CheckRow label="GSTIN / PAN match" value="Needs review" warning /><CheckRow label="Identity documents" value="3 of 4 received" warning /><button onClick={() => openAction("Open review workspace", "KYC queue")} className="mt-2 h-9 w-full rounded-lg bg-primary text-xs font-semibold text-primary-foreground">Open review workspace</button></div></WorkspaceCard></div>; }
function ScheduleWorkspace() { const { openAction } = useWorkspaceAction(); return <div className="grid gap-4 lg:grid-cols-[1fr_360px]"><WorkspaceCard title="Pickup schedule" detail="Today · Mumbai, Delhi, Bengaluru"><MetricStrip items={[["Scheduled", "46", "positive"], ["Unassigned", "7", "warning"], ["Failed", "3", "critical"]]} /><div className="grid gap-3 p-4 sm:grid-cols-3">{["08:00–10:00", "10:00–13:00", "13:00–16:00"].map((slot, i) => <button key={slot} onClick={() => openAction("Reserve pickup capacity", slot)} className="rounded-xl border border-border p-3 text-left hover:border-primary/40 hover:bg-primary/5"><p className="text-xs font-semibold">{slot}</p><p className="mt-2 text-2xl font-bold">{[12, 24, 10][i]}</p><p className="text-[10px] text-muted-foreground">{i === 1 ? "2 slots left" : "capacity available"}</p></button>)}</div><div className="divide-y divide-border/70">{["Northwind Pharma · Andheri", "Arvind Components · Bhiwandi", "Jaipur Craft House · Mansarovar"].map((item, i) => <div key={item} className="flex items-center gap-3 px-4 py-3"><Truck className="size-4 text-primary" /><span className="flex-1 text-xs font-semibold">{item}<span className="mt-1 block text-[10px] font-normal text-muted-foreground">{i === 1 ? "Unassigned · cutoff in 28 min" : "Driver assigned · 10:00–13:00"}</span></span><button onClick={() => openAction(i === 1 ? "Assign pickup driver" : "Open pickup detail", item)}><StatusBadge tone={i === 1 ? "warning" : "positive"}>{i === 1 ? "Assign" : "Scheduled"}</StatusBadge></button></div>)}</div></WorkspaceCard><WorkspaceCard title="Standalone request" detail="Schedule pickup even without an existing booking"><div className="space-y-3 p-4"><FieldBox label="Client / location" value="Choose pickup location" /><FieldBox label="Preferred slot" value="Tomorrow · 10:00–13:00" /><button onClick={() => openAction("Create pickup request", "Standalone request")} className="h-9 w-full rounded-lg bg-primary text-xs font-semibold text-primary-foreground">Create pickup request</button></div></WorkspaceCard></div>; }
function DirectoryWorkspace({ query, setQuery }: { query: string; setQuery(v: string): void }) { return <WorkspaceCard title="Client directory" detail="Account health and operational ownership"><Toolbar query={query} setQuery={setQuery} placeholder="Search client, code, city, or owner" /><div className="divide-y divide-border/70">{["Northwind Pharma", "Arvind Components", "Jaipur Craft House", "Orion Auto Parts"].filter((item) => item.toLowerCase().includes(query.toLowerCase())).map((name, i) => <div key={name} className="grid gap-2 px-4 py-3 sm:grid-cols-[1.4fr_1fr_130px_110px] sm:items-center"><span><span className="block text-xs font-semibold">{name}</span><span className="text-[10px] text-muted-foreground">CL-00{i + 18} · {['Mumbai', 'Delhi', 'Jaipur', 'Pune'][i]}</span></span><span className="text-[11px] text-muted-foreground">{['Rahul Sharma', 'Priya Mehta', 'Unassigned', 'Amit Shah'][i]}</span><span className="text-[11px] font-semibold">{[211, 84, 36, 159][i]} shipments</span><StatusBadge tone={i === 2 ? "warning" : "positive"}>{i === 2 ? "At risk" : "Healthy"}</StatusBadge></div>)}</div></WorkspaceCard>; }
function OrganizationWorkspace() { return <div className="grid gap-4 lg:grid-cols-[1fr_360px]"><WorkspaceCard title="Department capacity" detail="Ownership and manager coverage"><div className="divide-y divide-border/70">{["Operations", "Client Success", "Finance", "Technology"].map((name, i) => <div key={name} className="flex items-center gap-3 px-4 py-4"><div className="grid size-9 place-items-center rounded-lg bg-primary/10 text-primary"><Users className="size-4" /></div><span className="min-w-0 flex-1"><span className="block text-xs font-semibold">{name}</span><span className="mt-1 block text-[10px] text-muted-foreground">{[18, 7, 4, 3][i]} members · manager {['Amit Shah', 'Priya Mehta', 'Neha Rao', 'Rahul Sharma'][i]}</span></span><span className="text-xs font-bold">{[78, 62, 46, 71][i]}%</span></div>)}</div></WorkspaceCard><WorkspaceCard title="Coverage gaps" detail="Decisions for the organization owner"><div className="space-y-3 p-4"><CheckRow label="Every client has an owner" value="92%" warning /><CheckRow label="Managers have active deputies" value="3 gaps" warning /><CheckRow label="Disabled identities reviewed" value="Complete" /></div></WorkspaceCard></div>; }
function TasksWorkspace() { const { openAction } = useWorkspaceAction(); return <div className="grid gap-4 md:grid-cols-3">{[["Overdue", "4", "critical"], ["Due today", "12", "warning"], ["In progress", "28", "positive"]].map(([title, count, tone]) => <WorkspaceCard key={title} title={title} detail={`${count} tasks in this view`}><div className="divide-y divide-border/70">{["Review failed pickup", "Approve client transfer", "Resolve SLA breach"].slice(0, title === "Overdue" ? 2 : 3).map((task) => <button key={task} onClick={() => openAction("Open task", task)} className="flex w-full items-center gap-2 px-4 py-3 text-left hover:bg-muted/50"><ListChecks className={cn("size-4", tone === "critical" ? "text-destructive" : tone === "warning" ? "text-amber-500" : "text-emerald-500")} /><span className="flex-1 text-xs font-semibold">{task}</span><ChevronRight className="size-3 text-muted-foreground" /></button>)}</div></WorkspaceCard>)}</div>; }
function InboxWorkspace({ query, setQuery, filter, setFilter, rows }: { query: string; setQuery(v: string): void; filter: string; setFilter(v: string): void; rows: typeof sampleRows[number][] }) { const { openAction } = useWorkspaceAction(); return <div className="grid gap-4 xl:grid-cols-[minmax(0,1fr)_340px]"><WorkspaceCard title="Priority inbox" detail="Messages and events requiring an operator response"><Toolbar query={query} setQuery={setQuery} filter={filter} setFilter={setFilter} placeholder="Search ticket, client, or shipment" />{rows.map((row) => <Row key={row[0]} item={row} />)}</WorkspaceCard><WorkspaceCard title="Conversation context" detail="Select a message to open the full thread"><div className="p-4"><div className="rounded-lg bg-muted/40 p-3"><p className="text-xs font-semibold">Northwind Pharma</p><p className="mt-1 text-[10px] text-muted-foreground">Shipment PSS-2026-004821 · Priority support</p></div><div className="mt-4 space-y-3"><p className="rounded-lg bg-muted p-3 text-[11px] leading-5">“The delivery attempt is still not visible in our portal.”</p><p className="ml-8 rounded-lg bg-primary/10 p-3 text-[11px] leading-5">Assigned to Rahul Sharma. Response due in 18 minutes.</p></div><button onClick={() => openAction("Reply to support thread", "PSS-2026-004821")} className="mt-4 flex h-9 w-full items-center justify-center gap-2 rounded-lg border border-border text-xs font-semibold hover:bg-muted"><Send className="size-3.5" />Reply to thread</button></div></WorkspaceCard></div>; }
