function AnalyticsWorkspace() { return <div className="grid h-full gap-4 xl:grid-cols-[1.4fr_1fr]"><WorkspaceCard title="Operating trend" detail="Last 30 days · shipments, SLA, and exceptions"><div className="p-4"><div className="flex h-48 items-end gap-2 border-b border-l border-border p-3">{[42, 58, 51, 72, 66, 84, 76, 92, 81, 96, 88, 100].map((height, i) => <div key={i} className="group flex flex-1 items-end justify-center"><div className="w-full rounded-t bg-primary/70 transition-all group-hover:bg-primary" style={{ height: `${height}%` }} /></div>)}</div><div className="mt-3 flex justify-between text-[10px] text-muted-foreground"><span>Jul 14</span><span>Jul 29</span><span>Aug 12</span></div></div></WorkspaceCard><WorkspaceCard title="Performance mix" detail="Current operating distribution"><div className="space-y-4 p-4"><Progress label="On-time delivery" value="94.8%" width={95} tone="positive" /><Progress label="First-attempt success" value="82.1%" width={82} /><Progress label="Exception closure" value="76.4%" width={76} tone="warning" /><Progress label="SLA compliance" value="91.2%" width={91} tone="positive" /></div></WorkspaceCard></div>; }
