function IntegrationsWorkspace() { return <WorkspaceCard title="Connection health" detail="External services and delivery channels"><div className="divide-y divide-border/70">{["Delhivery API", "Blue Dart API", "Email · transactional", "WhatsApp · support", "Webhook · client events"].map((service, i) => <div key={service} className="flex items-center gap-3 px-4 py-3"><div className={cn("grid size-8 place-items-center rounded-lg", i === 1 ? "bg-amber-500/10 text-amber-600" : "bg-emerald-500/10 text-emerald-600")}><Gauge className="size-4" /></div><span className="flex-1"><span className="block text-xs font-semibold">{service}</span><span className="mt-1 block text-[10px] text-muted-foreground">{i === 1 ? "Latency elevated · 840ms" : `${i + 1} successful checks · credentials healthy`}</span></span><span className="font-mono text-[10px] text-muted-foreground">{i === 1 ? "Degraded" : "Connected"}</span><ChevronRight className="size-3.5 text-muted-foreground" /></div>)}</div></WorkspaceCard>; }
function SecurityWorkspace() { const { openAction } = useWorkspaceAction(); return <div className="grid h-full gap-4 lg:grid-cols-[1fr_360px]"><WorkspaceCard title="Active sessions" detail="Revoke access when identity or location is unexpected"><div className="divide-y divide-border/70">{["Gaurav Sharma · Chrome / Windows", "Rahul Sharma · Edge / Windows", "Unknown device · Chrome / Linux"].map((session, i) => <div key={session} className="flex items-center gap-3 px-4 py-4"><div className={cn("grid size-8 place-items-center rounded-lg", i === 2 ? "bg-destructive/10 text-destructive" : "bg-primary/10 text-primary")}><LockKeyhole className="size-4" /></div><span className="flex-1"><span className="block text-xs font-semibold">{session}</span><span className="mt-1 block text-[10px] text-muted-foreground">{['Current session · Mumbai', 'Active 2h ago · Delhi', 'Risk signal · new location'][i]}</span></span><button onClick={() => openAction("Revoke session", session)} className="rounded-lg border border-border px-2.5 py-1.5 text-[10px] font-semibold hover:bg-muted">Revoke</button></div>)}</div></WorkspaceCard><WorkspaceCard title="Security posture" detail="Current access signals"><div className="space-y-3 p-4"><Progress label="MFA coverage" value="86%" width={86} tone="positive" /><Progress label="Privileged review" value="92%" width={92} tone="positive" /><Progress label="Unknown sessions" value="1" width={18} tone="critical" /></div></WorkspaceCard></div>; }
function QueueOrSettingsWorkspace({ kind, query, setQuery, filter, setFilter, rows }: { kind: string; query: string; setQuery(v: string): void; filter: string; setFilter(v: string): void; rows: typeof sampleRows[number][] }) { const { openAction } = useWorkspaceAction(); if (kind === "settings") return <div className="grid h-full gap-4 lg:grid-cols-[1fr_340px]"><WorkspaceCard title="Organization defaults" detail="Changes affect future workflows only"><div className="divide-y divide-border/70">{["Default timezone", "Default shipment retention", "Require approval for wallet adjustments", "Enable operational email alerts"].map((label, i) => <div key={label} className="flex items-center gap-3 px-4 py-4"><Settings2 className="size-4 text-primary" /><span className="flex-1 text-xs font-semibold">{label}</span><span className="text-[11px] text-muted-foreground">{['Asia/Kolkata', '90 days', 'Enabled', 'Enabled'][i]}</span><ChevronRight className="size-3.5 text-muted-foreground" /></div>)}</div></WorkspaceCard><WorkspaceCard title="Change boundary" detail="Local prototype control"><div className="space-y-3 p-4"><p className="text-[11px] leading-5 text-muted-foreground">Settings are shown as local controls. Production persistence and audit enforcement are not connected yet.</p><button onClick={() => openAction("Review pending changes", "Organization defaults")} className="h-9 w-full rounded-lg bg-primary text-xs font-semibold text-primary-foreground">Review pending changes</button></div></WorkspaceCard></div>; return <div className="grid h-full gap-4 xl:grid-cols-[minmax(0,1fr)_320px]"><WorkspaceCard title="Priority queue" detail="Sort by severity, ageing, and accountable owner"><MetricStrip items={[["Open items", "37", "critical"], ["Due within 1 hour", "9", "warning"], ["Resolved today", "24", "positive"]]} /><Toolbar query={query} setQuery={setQuery} filter={filter} setFilter={setFilter} placeholder="Search alert, entity, or owner" />{rows.map((row) => <Row key={row[0]} item={row} />)}</WorkspaceCard><WorkspaceCard title="Decision panel" detail="Select an item to see recommended action"><div className="space-y-4 p-4"><div className="rounded-lg border border-destructive/20 bg-destructive/5 p-3"><div className="flex items-center gap-2"><CircleAlert className="size-4 text-destructive" /><p className="text-xs font-semibold">Shipment exception</p></div><p className="mt-2 text-[11px] leading-5 text-muted-foreground">A shipment is waiting for an accountable owner and next action.</p></div><DetailLine label="Owner" value="Unassigned" /><DetailLine label="Age" value="42 minutes" /><button onClick={() => openAction("Assign and open detail", "Shipment exception")} className="h-9 w-full rounded-lg bg-primary text-xs font-semibold text-primary-foreground">Assign and open detail</button></div></WorkspaceCard></div>; }

function FieldBox({ label, value }: { label: string; value: string }) { const { openAction } = useWorkspaceAction(); return <button onClick={() => openAction(`Set ${label}`, value)} className="block w-full text-left"><span className="mb-1.5 block text-[11px] font-semibold">{label}</span><span className="flex h-10 items-center justify-between rounded-lg border border-input bg-background px-3 text-xs text-muted-foreground"><span>{value}</span><ChevronRight className="size-3.5" /></span></button>; }
function CheckRow({ label, value, warning = false }: { label: string; value: string; warning?: boolean }) { return <div className="flex items-center gap-3 px-4 py-3"><span className={cn("grid size-6 place-items-center rounded-full", warning ? "bg-amber-500/10 text-amber-600" : "bg-emerald-500/10 text-emerald-600")}>{warning ? <CircleAlert className="size-3.5" /> : <Check className="size-3.5" />}</span><span className="flex-1 text-xs font-semibold">{label}</span><span className={cn("text-[10px] font-semibold", warning ? "text-amber-600" : "text-muted-foreground")}>{value}</span></div>; }
function DetailLine({ label, value }: { label: string; value: string }) { return <div className="flex items-center justify-between gap-4 border-b border-border/60 pb-2 text-[11px]"><span className="text-muted-foreground">{label}</span><span className="text-right font-semibold">{value}</span></div>; }
function Progress({ label, value, width, tone = "neutral" }: { label: string; value: string; width: number; tone?: Tone }) { return <div><div className="flex justify-between text-[11px]"><span className="font-semibold">{label}</span><span className="font-mono text-muted-foreground">{value}</span></div><div className="mt-1.5 h-1.5 overflow-hidden rounded-full bg-muted"><div className={cn("h-full rounded-full", tone === "positive" ? "bg-emerald-500" : tone === "warning" ? "bg-amber-500" : tone === "critical" ? "bg-destructive" : "bg-primary")} style={{ width: `${width}%` }} /></div></div>; }
function ActionDialog({ action, onClose, onSubmit }: { action: WorkspaceAction | null; onClose(): void; onSubmit(payload: ActionPayload): void }) {
  const fields = action ? actionFields(action.label) : [];
  const [values, setValues] = useState<ActionPayload>(() => Object.fromEntries(fields.map((field) => [field.key, field.options?.[0]?.value ?? ""])))
  function setValue(key: string, value: string) { setValues((current) => ({ ...current, [key]: value })); }
  const valid = fields.every((field) => !field.required || values[field.key]?.trim());
  return <Modal open={Boolean(action)} onClose={onClose} title={action?.label ?? "Workspace action"} description="Complete the operational fields that the backend action will receive."><div className="space-y-4"><div className="rounded-lg bg-muted/40 p-3"><p className="text-xs font-semibold">{action?.entity ?? "Selected workspace item"}</p><p className="mt-1 text-[10px] text-muted-foreground">{action?.label}</p></div><div className="grid h-full gap-4 sm:grid-cols-2">{fields.map((field) => <label key={field.key} className={cn("block", field.type === "textarea" && "sm:col-span-2")}><span className="mb-1.5 block text-xs font-semibold">{field.label}{field.required && <span className="ml-1 text-destructive">*</span>}</span>{field.type === "select" ? <Dropdown label={field.label} value={values[field.key] ?? ""} options={field.options ?? []} onChange={(value) => setValue(field.key, value)} /> : field.type === "textarea" ? <textarea value={values[field.key] ?? ""} onChange={(event) => setValue(field.key, event.target.value)} className="min-h-24 w-full resize-y rounded-lg border border-input bg-background p-3 text-xs outline-none focus:border-primary focus:ring-4 focus:ring-primary/10" placeholder={field.placeholder} /> : <input type={field.type} value={values[field.key] ?? ""} onChange={(event) => setValue(field.key, event.target.value)} className={cn(inputClass, "h-9 text-xs")} placeholder={field.placeholder} />}</label>)}</div><div className="flex justify-end gap-2 border-t border-border/70 pt-4"><button type="button" onClick={onClose} className="h-9 rounded-lg border border-border px-3 text-xs font-semibold hover:bg-muted">Cancel</button><button type="button" disabled={!valid} onClick={() => onSubmit(values)} className="h-9 rounded-lg bg-primary px-3 text-xs font-semibold text-primary-foreground hover:bg-primary/90 disabled:cursor-not-allowed disabled:opacity-50">Save {action?.label}</button></div></div></Modal>;
}

type ActionField = { key: string; label: string; type: "text" | "date" | "textarea" | "select"; placeholder?: string; required?: boolean; options?: { value: string; label: string }[] };
