  if (/^configure sla$/i.test(label)) return [select("slaType", "SLA type", ["Support response", "Support resolution", "Pickup recovery", "Shipment exception"]), { key: "responseHours", label: "Response threshold (hours)", type: "text", placeholder: "e.g. 4", required: true }, { key: "resolutionHours", label: "Resolution threshold (hours)", type: "text", placeholder: "e.g. 24", required: true }, select("calendar", "Working calendar", ["Business hours · Mon–Sat", "24 × 7", "Custom calendar"]), select("escalation", "Escalation chain", ["Owner → Manager", "Owner → Super Admin", "Owner → Courier manager"]), select("channels", "Notification channels", ["Email and portal", "Email, WhatsApp and portal", "Portal only"]), select("status", "Policy status", ["Active", "Draft", "Paused"]), { key: "breach", label: "Breach condition", type: "textarea", placeholder: "Define when the policy should escalate.", required: true }];
