  if (/alert rule|notification rule/i.test(label)) return [select("trigger", "Trigger", ["Shipment delayed", "Pickup failed", "New client submitted", "Invoice overdue"]), { key: "condition", label: "Condition", type: "textarea", placeholder: "Describe when this rule should run.", required: true }, select("action", "Action", ["Notify owner", "Create exception", "Escalate to Super Admin"]), select("status", "Status", ["Active", "Paused"])]
